quests[11018] = { id = 11018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nethercite Ore", description = "A miner!\n\n<Varkule salutes.>\n\nAn orc after my own heart! That's how Varkule got his start - minin'! There ain't nothin' better than getting down and dirty in the mines, is there?\n\nNow get out there and find those nethercite deposits. Strip 'em for all their worth and bring me back the ore.", sourceObjective = "Taskmaster Varkule Dragonbreath at Dragonmaw Base Camp in Shadowmoon Valley wants you to bring him 40 Nethercite Ore.", progress = "Gug over there is gonna use the ore to reinforce our weapons and armor.", completion = "You're done for today, kid. Come back tomorrow if you're still alive.", sourceObjectiveStatus = "unverified-source-field" }
quests[11019] = { id = 11019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Friend On The Inside", sourceObjective = "Didn't think we'd leave you to face the fel orc army by yourself, did you?\n\n<Yarzill's eyes flicker a translucent blue.>\n\nAye, we are here with you, {name}. For every service you perform for the fel orcs in your quest to reclaim Netherwing lands, we'll be at your side to make sure that they suffer a sufficient setback.\n\nYou'll need to keep a low profile so as not to draw any unwanted attention to yourself during your sabotage missions.", sourceObjectiveStatus = "unverified-source-field" }
quests[11020] = { id = 11020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Slow Death", description = "The Dragonmaw have peons stationed at nearly every crystal formation up here. While the outright slaying of them would draw far too much unwanted attention to you, there is a way that we can thin their numbers and remain below the suspicious eyes of Mor'ghor.\n\nVenture into the wilds of Shadowmoon Valley and slay the tainted wildlife. Take from them their corrupt fel glands. Use those fel glands with this mutton that I'll give you near the peons. They'll take one bite and fall deathly ill!", sourceObjective = "Yarzill the Merc at Dragonmaw Base Camp in Shadowmoon Valley wants you to use Yarzill's Mutton in conjunction with Fel Glands to poison 12 Dragonmaw Peon Camps.", progress = "It is dirty work, {name}.", completion = "<Yarzill speaks in a low whisper.>\n\nExcellent work, {name}. Lay low for now. Come back to me tomorrow and we can do it again.", sourceObjectiveStatus = "unverified-source-field" }
quests[11021] = { id = 11021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ishaal's Almanac", description = "This mysterious tome was on Talonpriest Ishaal's body.  It contains arcane symbols and charts of celestial bodies beyond your comprehension.\n\nAll writing is in a language you don't understand; likely an ancient version of the arakkoa written tongue.  Perhaps you should bring this to Sky Commander Adaris.", sourceObjective = "Bring Ishaal's Almanac to Sky Commander Adaris north of Skettis.", progress = "You've something to show me?", completion = "What have you brought to me?  I can't make out the writing on this tome, {name}... my loss of blood... must've blurred my vision.", sourceObjectiveStatus = "unverified-source-field" }
quests[11022] = { id = 11022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Mog'dorg", description = "<King/Queen> {name}!  You speak with Mog'dorg the Wizened before you leave and go to Ogri'la!", sourceObjective = "Speak with Mog'dorg the Wizened. He stands atop the tower on the east side of the Circle of Blood in the Blade's Edge Mountains.", completion = "My good man, I am glad that you have decided to speak to me again before leaving.", sourceObjectiveStatus = "unverified-source-field" }
quests[11023] = { id = 11023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bomb Them Again!", description = "We're still having problems with those flak cannons, {name}.\n\nDon't get me wrong -- I think that you did an outstanding job the last time out -- but, that doesn't change the fact that those damned demons seem to be replenishing their ammo supplies faster than we can knock them out.  And that means we're having a hell of a time getting our people through there, not to mention the risk those demons pose to Ogri'la.\n\nWhat do you say?  Want to take another shot at it?", sourceObjective = "Use the Skyguard Bombs to destroy 15 Fel Cannonball Stacks.", progress = "How goes the bombing run?", completion = "Outstanding work, {name}!  I'd have you back up in the air and bombing them again, but policy around here is to make sure that our pilots get plenty of R&R.  Sorry, I don't make the rules, but I sure as hell enforce them!\n\nSee you again tomorrow, Ace!", sourceObjectiveStatus = "unverified-source-field" }
quests[11024] = { id = 11024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ally in Lower City", description = "There is an arakkoa in Lower City by the name of Rilak...  He can be trusted.  Take the book... to him.\n\n<Adaris drifts into unconsciousness as he returns the book to you.>", sourceObjective = "Bring Ishaal's Almanac to Rilak the Redeemed in the Lower City section of Shattrath City.", progress = "You have the smell of Skettis on you!  Explain yourself!", completion = "This cannot be... this belonged to a talonpriest once.  How did you ever come across it?", sourceObjectiveStatus = "unverified-source-field" }
quests[11025] = { id = 11025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crystals", description = "When prepared correctly, the crystals of the mountains exhibit strange powers, such as the clarity of mind that we have found here in Ogri'la.\n\nAll of the creatures atop the mountains covet the crystal shards and use them to further their own goals.  An economy has even sprung up around them.\n\nTo assist us, you must first learn about the Apexis shards.  Bring me some.  In addition to the creatures here having them, they can sometimes be found where the flayers dig at the larger crystals.", sourceObjective = "Chu'a'lor has tasked you with gathering 5 Apexis Shards. Bring them to him at Ogri'la atop the Blade's Edge Mountains.", progress = "As you come to understand the shards and crystals, you will be better able to assist us in protecting ourselves and our ogre brethren below.\n\nThe shards themselves get their name from an ancient and now-extinct arakkoan civilization, which used to live atop the mountains here.\n\nDo you have the shards with you?", completion = "<Chu'a'lor's left head begins to speak.>\n\nThese will do fine.\n\nRemember, {name}, the value of the shard is not in what it can purchase for you.  It is not even in what it can potentially do for you when properly forged, though there is some debate over that.\n\n\n\nThe true value is in the journey to attain the shard.", sourceObjectiveStatus = "unverified-source-field" }
quests[11026] = { id = 11026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Banish the Demons", description = "You've arrived at the perfect time, friend!  We are in need of assistance.  In return, you will receive something very rare, which will help us both in the end.\n\nWe're not a violent ogre any longer, but the demons nearby threaten to overrun us and the Skyguard.  The problem with demons is that, once killed, they come right back in new bodies!\n\nBut, if you use this crystal to summon a banishing portal, when they die near it, their essences will be drawn in and banished back from whence they came!", sourceObjective = "Use the Banishing Crystal to banish 15 demons at Forge Camp: Wrath or Forge Camp: Terror.", progress = "We trust that you've used the banishing crystal to send a whole slew of those Burning Legion things packing?!", completion = "That'll teach them!  And, of course, now for your reward.\n\nThe demons of Forge Camp: Wrath, to the north, have created a special transporter on their southern border.   This experimental gate is being used to expand the forge camp, and we don't think we need to tell you how that will effect us if they expand too far.\n\nHowever, if we were you, we'd take this darkrune over to Gahk, and ask him how you can help.  Just take it easy on him, {name}.  Like you, he's new here.", sourceObjectiveStatus = "unverified-source-field" }
quests[11027] = { id = 11027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yous Have Da Darkrune?" }
quests[11028] = { id = 11028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Countdown to Doom", description = "This almanac presages the return of Terokk, the most powerful and terrible Skettis king in arakkoa history.\n\nI always believed this to be the mere legend, {name}.  The return of the talonpriests and your recovery of this tome indicate otherwise.\n\nWith each day, Terokk comes closer to returning to full strength.  Your only chance is to bring him to our world prematurely.  Return to Skettis and speak to Adaris about this.  Let us hope he has the wisdom to do the right thing.", sourceObjective = "Return to Sky Commander Adaris at Blackwind Landing in Terokkar Forest with the news about Terokk's return.", completion = "The arakkoa seek to bring Terokk back beyond the veil of time and Rilak... wants to find a way to accelerate the process?  Is he out of his mind?\n\n<Adaris lays back down as his strength fades.>\n\nYou've done your duty, {name}.  It is time you let my men take over from here.  This has become a purely military matter.", sourceObjectiveStatus = "unverified-source-field" }
quests[11029] = { id = 11029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shabby Disguise", description = "Open the package, {name}.  It is a disguise.  It doesn't look very convincing, does it?\n\nI craft them for ethereal smugglers in search of rare books.  There is an arakkoa scribe who dwells in the central island in Skettis, Terokk's Rest; his name is Sahaak.  He is old and nearly blind.\n\nUse the disguise to speak with him and obtain the book known as the Adversarial Bloodlines.  Be careful, {name}.  The disguise won't fool the other arakkoa.", sourceObjective = "Use the Shabby Arakkoa Disguise to obtain the Adversarial Bloodlines from Sahaak and return to Hazzik.", progress = "The book, {name}.  Have you obtained it?", completion = "Excellent!  This book catalogs the descendants of Terokk's ancient enemies.  It is prophesied that their demise will be followed by Terokk's return.", sourceObjectiveStatus = "unverified-source-field" }
quests[11030] = { id = 11030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Boy Wants To Be A Skyguard Ranger", description = "{class}, we've got a problem -- we have lots of sons.  And ever since the Skyguard moved in nearby, all our sons ever talk about is joining their ranks.\n\nAs a proud father, we want them to have every advantage for when they apply.  So, would you go to the fel crystalforge at either forge camp to the north or south, and procure a magic flask for our sons?  You can't miss their green smoke.\n\nWe think that they take ten apexis shards to make.  We'd give you the shards, but we don't have any at the moment.", sourceObjective = "Collect an Unstable Flask of the Beast.", progress = "You have that magic flask, yet?  It will mean the world to little Torkus Jr.", completion = "You're a lifesaver, {name}.  Our boys are going to be so excited to hear the news!\n\nOK, so one down and one to go.  We did tell you about the other magical flask that they're going to need, didn't we?", sourceObjectiveStatus = "unverified-source-field" }
quests[11031] = { id = 11031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archmage No More", progress = "You've decided against your previous choice?  I suppose I can help you reverse it.  In the end Dalaran cares more about your loyalty than how you choose to show it.\n\nIt won't be cheap.  And of course, I will need your old ring back.", completion = "Make this next decision carefully.  We do our best to accommodate our allies, but even Dalaran's resources have their limits." }
quests[11032] = { id = 11032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protector No More", progress = "You've decided against your previous choice?  I suppose I can help you reverse it.  In the end Dalaran cares more about your loyalty than how you choose to show it.\n\nIt won't be cheap.  And of course, I will need your old ring back.", completion = "Make this next decision carefully.  We do our best to accommodate our allies, but even Dalaran's resources have their limits." }
quests[11033] = { id = 11033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assassin No More", progress = "You've decided against your previous choice?  I suppose I can help you reverse it.  In the end Dalaran cares more about your loyalty than how you choose to show it.\n\nIt won't be cheap.  And of course, I will need your old ring back.", completion = "Make this next decision carefully.  We do our best to accommodate our allies, but even Dalaran's resources have their limits." }
quests[11034] = { id = 11034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restorer No More", progress = "You've decided against your previous choice?  I suppose I can help you reverse it.  In the end Dalaran cares more about your loyalty than how you choose to show it.\n\nIt won't be cheap.  And of course, I will need your old ring back.", completion = "Make this next decision carefully.  We do our best to accommodate our allies, but even Dalaran's resources have their limits." }
quests[11035] = { id = 11035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Not-So-Friendly Skies...", description = "On the northeast edge of this island exists a dock used for the packaging and transport of Netherwing crystals and relics. Dragonmaw Transporters transport the goods from the dock to Dragonmaw Fortress while Dragonmaw Ascendants guard the ground from any would-be attackers.\n\nThis leaves one opening for you to make a strike at the Dragonmaw: The Dragonmaw Skyway.\n\nFly to the shattered islands of the Dragonmaw Skyway and ambush the transporters that use the route. Recover our stolen relics!", sourceObjective = "Yarzill the Merc at Dragonmaw Base Camp in Shadowmoon Valley wants you to recover 10 Netherwing Relics.", progress = "Dead orcs tell no tales, {name}. Make sure those Dragonmaw transporters do not escape.", completion = "<Yarzill whispers.>\n\nYou are doing the Netherwing a great service, {name}. Slowly, we will topple the Dragonmaw. From the inside a disease now grows - a disease with no cure...\n\nReturn to me tomorrow if you are interested in more work at the Dragonmaw Skyway.", sourceObjectiveStatus = "unverified-source-field" }
quests[11036] = { id = 11036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of This World Produce!", description = "I'll be the first to admit I'm not quite sure what this order is for, but Rocket-Chief Fuselage's instructions were very specific -- only the very best fruit, preserved to survive a long voyage and sealed against the elements.\n\nThere were other specifications, zero-gravity this and low pressure that. I don't pretend to understand it, but the price is right, so he'll get his superfood. Bring this crate to him up at Area 52. After crossing into Netherstorm, keep following the road until you see the town.", sourceObjective = "Bring the Preserved Fruit to Rocket-Chief Fuselage at Area 52 in the Netherstorm.", progress = "Is that the delivery from Old Orok?", completion = "<The chief inspects the crate's contents.>\n\nEverything looks good here. That's one more thing to cross off the list. Now all we need to do is get the rocket off the ground!", sourceObjectiveStatus = "unverified-source-field" }
quests[11037] = { id = 11037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strange Vision", description = "I've had a most unusual vision, {name}, and I don't know quite what to make of it. I've seen an arrow, an immense arrow, riding into the sky on a trail of fire. Such a feat is trivial for a skilled mage, but somehow I know the arrow I saw is not the product of magic.\n\nIt will be unlike anything the people of Azeroth have ever achieved. You must seek out the people working on this, {name}. Lend them your help, for without it, their efforts may yet fail.", sourceObjective = "Speak with Rocket-Chief Fuselage at Area 52.", completion = "<The chief listens as you describe the seer's vision.>\n\nWell, I don't know about any of that, but we could certainly use your help around here. Behold the rocket behind me! That's the X-52...\n\nIsn't it the most beautiful thing you've ever seen?", sourceObjectiveStatus = "unverified-source-field" }
quests[11038] = { id = 11038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assist Exarch Orelis", description = "Not long ago, High Priestess Ishanah sent a small group of anchorites to Netherstorm, under the command of Exarch Orelis. They were to investigate the activities of Kael'thas and his minions, but we haven't received any reports of their findings yet.\n\nI worry that our presence in the area might not be strong enough to carry out the mission. I'm certain that the exarch could benefit from your knowledge and experience. Are you willing to travel to Area 52 and assist him?", sourceObjective = "Speak with Exarch Orelis at Area 52.", completion = "So you're here to help us determine exactly what Kael'thas is planning? Your help is most welcome. Netherstorm is crawling with blood elf agents whose activities threaten to tear the land asunder.", sourceObjectiveStatus = "unverified-source-field" }
quests[11039] = { id = 11039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Spymaster Thalodien", description = "Some time ago, Voren'thal dispatched a small team to Netherstorm to investigate the activities of Kael'thas. Our leader has the utmost confidence in Spymaster Thalodien and his compatriots, and has decided to honor his request for reinforcements.\n\nThalodien's report was brief, but clear that he's encountered something of great importance. Report to him at Area 52 and assist him in any way possible, {name}.", sourceObjective = "Report to Spymaster Thalodien at Area 52.", completion = "<A brief look of disappointment crosses the spymaster's face.>\n\nI was hoping for at least a squad, but if Voren'thal saw fit to send only you, then I will adjust my plans accordingly.", sourceObjectiveStatus = "unverified-source-field" }
quests[11040] = { id = 11040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parts for the Rocket-Chief", description = "You can count on one hand the number of times I've collaborated with a goblin. We're far more likely to be in competition with them, but when I received Rocket-Chief Fuselage's request, I just couldn't refuse him.\n\nThis crate is full of parts I'm not using here, but that the rocket-chief might be able to put to use on his project. Would you be kind enough to deliver them if you're on your way to Area 52?\n\nWho knows, maybe some fine gnomish parts could keep his creation from exploding!", sourceObjective = "Bring Bossi's Spare Parts to Rocket-Chief Fuselage at Area 52 in the Netherstorm.", progress = "That crate has the look of a master gnomish engineer about it. Did Bossi send you?", completion = "I don't even know what some of these parts do! I'm certain I'll find a use for some of them, but I never suspected I'd have to learn to think like a gnome!", sourceObjectiveStatus = "unverified-source-field" }
quests[11041] = { id = 11041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Job Unfinished...", description = "In the name of our great master... For the glory of Illidan!\n\nBy order of Overlord Mor'ghor, the great plateau of Netherwing Ledge is to be secured. With all Netherwing drakes captured or forced off of the land, rock flayers are running rampant and threatening crystal harvesting operations.\n\nDestroy them all, their den mother and her consort, Arvoar.\n\nMor'ghor commands it!\n\n<It would appear that this orc failed to take the plateau. It is time to prove your worth to Mor'ghor!>", sourceObjective = "Slay 10 Overmine Flayers and Barash the Den Mother. Return to Overlord Mor'ghor at the Dragonmaw Base Camp should you succeed.", progress = "Who dares approach Mor'ghor? This had better be important.", completion = "So from the remains of one of my own overseers you recovered the command and took matters into your own hands? You have managed to impress Mor'ghor. Well done...", sourceObjectiveStatus = "unverified-source-field" }
quests[11042] = { id = 11042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mystifying Vision", description = "A strange vision haunts me, {name}. I see a continuous cloud of smoke ascending toward the sky, left in the wake of a giant fire moving ever faster away. It is not a natural phenomenon, nor a creation of evil; that much I know.\n\nI have no knowledge of what it looks like, save that it is the product of the labor of many. Yet, without more hands, it may never come to be.\n\nTravel to Netherstorm, {class}. Locate those responsible for this creation and offer them your aid.", sourceObjective = "Speak with Rocket-Chief Fuselage at Area 52.", completion = "<The chief listens as you describe the seer's vision.>\n\nWell, I don't know about any of that, but we could certainly use your help around here. Look at the behemoth behind me. That's the X-52...\n\nIsn't it the most beautiful thing you've ever seen?", sourceObjectiveStatus = "unverified-source-field" }
quests[11043] = { id = 11043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Building a Better Gryphon", description = "I've heard that the Wildhammer dwarves maintain a gryphon roost at their fortress down in southern Shadowmoon Valley. If you're going down there, would you speak to them on my behalf? I have some ideas on how to improve their gryphons!\n\nWhy stop at armoring them when you could attach an altimeter, a rear view mirror, and rocket? Imagine how fast you could go with one of those babies strapped to your gryphon's back! I'll call it the TurboGryphon 8000!", sourceObjective = "Speak with Brunn Flamebeard at Wildhammer Stronghold in Shadowmoon Valley.", completion = "<Brunn's face reddens until its color is indistinguishable from his beard.>\n\nHe wants to do WHAT to my gryphons?\n\nIf that little pipsqueak puts anything other than a saddle on them, I'll personally travel up to Blade's Edge and stuff that rocket o' his down his throat!", sourceObjectiveStatus = "unverified-source-field" }
quests[11044] = { id = 11044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visions of Destruction", description = "A vision of cataclysm often disturbs my rest -- a rain of green fire falling to the earth, felling the valiant defenders of a mighty fortress. It has haunted me for weeks now, although I have only recently come to understand its meaning.\n\nTo the far east, in Shadowmoon Valley, the Wildhammer dwarves endure constant attacks from the Burning Legion and numerous other foes. They fight bravely, but without relief, their enemies will triumph. Go to their side, {name}. Help them in their fight.", sourceObjective = "Speak with Wing Commander Nuainn at Wildhammer Stronghold.", completion = "A vision, you say? I don't care if he saw it in a vision, read it in a letter, or heard it from the mouth of a pit lord. He was dead on! What matters is that you're here, friend, and we need all the help we can get.", sourceObjectiveStatus = "unverified-source-field" }
quests[11045] = { id = 11045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorus the Judicator", description = "The history of Shadowmoon Valley is a long and troubled one. Few delve into it for fear of breathing new life into the unspeakable atrocities that took place there.\n\nNot all are so timid, though. Zorus the Judicator searches for the truth about the ghosts of Shadowmoon's past. It is a staggering undertaking, one with which he would welcome help, I'm sure.\n\nIf you should venture into the valley, look for Zorus at Wildhammer Stronghold, in the central portion of the valley's southern region.", sourceObjective = "Speak with Zorus the Judicator at Wildhammer Stronghold.", completion = "Fantei speaks the truth and I would welcome your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[11046] = { id = 11046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chief Apothecary Hildagard", description = "The history of Shadowmoon Valley is a long and troubled one. Few study it for fear of breathing new life into the unspeakable atrocities that took place there.\n\nNot all are so timid, though. Chief Apothecary Hildagard's research delves into the ghosts of Shadowmoon's past. It is a staggering undertaking, one with which she would welcome help, I'm sure.\n\nIf your travels bring you there, seek Hildagard at Shadowmoon Village, in the northwestern reaches of the valley.", sourceObjective = "Speak with Chief Apothecary Hildagard at Shadowmoon Village.", completion = "Fantei has a good memory. It's been months since I was last in Shattrath to buy reagents. He's right, though. I could use the help.", sourceObjectiveStatus = "unverified-source-field" }
quests[11047] = { id = 11047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Apprentice's Request", description = "As an apprentice wind rider master, one of my tasks is to care for the beasts when they're not flying. The problem is that we have so few here, there's very little downtime for any of them.\n\nI'm afraid we'll work them all to death if we don't receive any replacements. There's a large stable down in Shadowmoon Village, in western Shadowmoon Valley. Dama Wildmane oversees the wind rider care and training there.\n\nWould you speak with her on our behalf and let her know about our situation?", sourceObjective = "Speak with Dama Wildmane at Shadowmoon Village in Shadowmoon Valley.", completion = "<Dama listens to Agadai's request.>\n\nI can't guarantee that there will be any wind riders available, but I'll see what I can do. As it is, we're having trouble keeping up with the demands of other buyers and outposts.", sourceObjectiveStatus = "unverified-source-field" }
quests[11048] = { id = 11048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kroghan's Report", description = "My original orders were to remain in Garadar for a short time, then continue on and report to Blood Guard Gulmok at Shadowmoon Village. What I've seen in my time here is that Garadar could benefit from a long term Horde liaison.\n\nI know that Blood Guard Gulmok needs all the troops he can get, but I know he'll understand that my mission here isn't yet complete. Travel to Shadowmoon Village, in northwestern Shadowmoon Valley, and inform Blood Guard Gulmok of my delayed arrival.", sourceObjective = "Speak with Blood Guard Gulmok at Shadowmoon Village.", completion = "<Gulmok grumbles upon hearing of Kroghan's decision.>\n\nI understand his point of view, but we need warm bodies in the trenches here too! The Legion's bombarding us with infernals day and night. If Kroghan's going to be delayed, you can take his place on the field!", sourceObjectiveStatus = "unverified-source-field" }
quests[11049] = { id = 11049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Netherwing Egg Hunt", description = "Should you discover any Netherwing eggs while exploring, bring them to me.\n\nBe warned, a Netherwing egg is a rare discovery. Do not become frustrated if you cannot locate one. These Dragonmaw have been very thorough in collecting most of them and shipping them off to parts unknown.\n\nEggs might be found on creatures of the island, near crystal formations, in the mines, or even inside a nethercite node or netherdust bush.\n\nKeep a low profile. We don't need Mor'ghor catching wind of your actions.", sourceObjective = "Yarzill the Merc at Dragonmaw Base Camp in Shadowmoon Valley wants you to recover a Netherwing Egg.", progress = "How goes the egg hunt?", completion = "Neltharaku will be most pleased, {name}. Well done.", sourceObjectiveStatus = "unverified-source-field" }
quests[11050] = { id = 11050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Accepting All Eggs", progress = "We don't need those eggs to get into the wrong hands, {name}. Bring me any additional eggs that you may find.\n\nJust remember to keep a low profile and avoid raising suspicion!", completion = "You are a true hero, {name}." }
quests[11051] = { id = 11051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Banish More Demons", description = "If we know the demons, and we do because we've studied them extensively, they're fast at work repairing any damage that has been done to their precious transporter.\n\nSo, if you want a chance at another darkrune, take our banishing crystal back out there and eliminate more demons.  Besides, you want to help us to lessen the threat that the demons pose, yes?\n\nWe said \"chance\" because the process we use yields mixed results.  You might get a darkrune, or you might get something else entirely.", sourceObjective = "Use the Banishing Crystal to banish 15 demons at Forge Camp: Wrath or Forge Camp: Terror.", progress = "A seasoned pro such as yourself shouldn't be having any difficulty banishing demons.  You're not having any difficulties, right, {race}?", completion = "We wish the process of creating a darkrune was foolproof, {name}.  Alas, it is not.  Please, take this bag and look in it to see what we've wrought today.  We couldn't bear to look ourselves.\n\nRemember, if you get a darkrune, take it to Gahk to exchange for a crystalforged darkrune.  Then you'll be able to once more bring down Shartuul's transporter.\n\nOh, and {name}, don't forget to come by again tomorrow and pickup the banishing crystal.  There are always more demons to be banished.", sourceObjectiveStatus = "unverified-source-field" }
quests[11052] = { id = 11052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akama's Promise", description = "<Akama inserts the crystal into the medallion in his hand.>\n\nI am not as strong as I once was, {name}.  Being so close to evil itself all these years - I do not know if I can trust myself with an artifact as powerful as this.\n\nTake this as my promise to you that when the time comes and you face Illidan, I will be on your side.  Take it to the one being we know we can trust with its power.  Take the medallion to A'dal in Shattrath City.", sourceObjective = "Bring the Medallion of Karabor to A'dal in Shattrath City.", progress = "<A'dal notices your approach and a warm light embraces you.  A'dal seems to know you have something for him.>", completion = "<As you give the medallion to A'dal, it disappears into his being in a flash of light.>\n\n<You are briefly shown a glimpse of a moment... perhaps in the future.  You see Akama and Maiev coming out of the Warden's Cage, fighting their way to the Dark Temple.  A third figure shrouded in shadows is aiding them.  Upon closer inspection you notice that the figure is you.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11053] = { id = 11053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise, Overseer!", description = "Rare it is that a peon survives for as long as you have. Rarer still is when a peon rises from the dregs to attain a new rank.\n\n<Varkule claps.>\n\nThe Overlord has called for you, grunt. A new rank awaits, no doubt.", sourceObjective = "Speak with Overlord Mor'ghor at Dragonmaw Base Camp in Shadowmoon Valley.", completion = "I have been following your activities closely, {name}. You have proven to be an invaluable asset to Dragonmaw. With that said, I am going to promote you to Overseer. With that rank comes new responsibilities that you must fulfill.\n\nRise, Overseer {name}! Rise and seek out those that need your assistance at the base camp.", sourceObjectiveStatus = "unverified-source-field" }
quests[11054] = { id = 11054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overseeing and You: Making the Right Choices", description = "So you're the new overseer, eh? Well there's one thing any good overseer needs and that's the proper disciplinary weapon. Before you can go out there and knock some sense into these peons you need to have your \"piece.\" Each overseer has to gather the materials required to make their own \"piece\" and you'll be no different.\n\nI'll need knothide leather and the hardened hide of Tyrantus. You'll find Tyrantus in Eco-Dome Farfield, located in the northern reaches of Netherstorm.", sourceObjective = "Chief Overseer Mudlump at the Dragonmaw Base Camp in Shadowmoon Valley wants you to bring him 10 pieces of Knothide Leather and 1 Hardened Hide of Tyrantus.", progress = "There's peons to be disciplined, {name}! Hurry it up!", completion = "ARRR! You might make it as an overseer after all. That oversized lizard has been the bane of many an orc!\n\n<Chief Overseer Mudlump begins to fashion the weapon.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11055] = { id = 11055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Booterang: A Cure For The Common Worthless Peon", description = "This is your booterang. There are many like it but this one is yours.\n\nAs an overseer you will use this booterang to sow terror into the hearts of defiant peons. Proper use of the booterang will instill obedience and ensure subservience.\n\nVenture forth to the crystal fields and discipline any peons that you see slacking off. Show them the might of the booterang!", sourceObjective = "Chief Overseer Mudlump at the Dragonmaw Base Camp in Shadowmoon Valley wants you to discipline 20 lazy Dragonmaw Peons. You will also need to return your Booterang.", progress = "It's all in the wrist, {name}.", completion = "A hard day's work! It pays off, though, doesn't it? Warms your heart seeing those worthless runts slavering over those crystals... Anyhow, that's all for today. Come back tomorrow for another round of booterang discipline.", sourceObjectiveStatus = "unverified-source-field" }
quests[11056] = { id = 11056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hazzik's Bargain", description = "Do not draw attention to our conversation.  Adaris would not approve.\n\nI belong to the lowest caste of arakkoa, {name}.  During Terokk's rule I would've been sacrificed to the dark powers worshipped by his talonpriests.  If what you say is true and the talonpriests are seeking Terokk's return, then you must prevent them from succeeding - regardless of what your leader says!\n\nI've something to offer you that you'll find useful.  There is a package at my old dwelling in Upper Veil Shil'ak.  Bring it to me!", sourceObjective = "Obtain Hazzik's Package at his dwelling in eastern Skettis and return to him with it.", progress = "You've returned, {name}.  I was beginning to think you'd given up on me.", completion = "Excellent, {name}.  You will see that I'm true to my word.", sourceObjectiveStatus = "unverified-source-field" }
quests[11057] = { id = 11057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trouble Below", description = "We commend your zeal in wanting to help out here in Ogri'la, {class}.  However, we have a favor to ask of you before we can accept your assistance.\n\nDown below our brethren are enslaved to the Sons of Gruul.  Please, speak with Mog'dorg the Wizened, who is leading an ogre resistance against their gronn masters.\n\nSeek him out atop the tower on the eastern side of the Circle of Blood arena.", sourceObjective = "Speak with Mog'dorg the Wizened atop one of the towers just outside the Circle of Blood in the Blade's Edge Mountains.", completion = "You were sent from on high?  Truly my mission is blessed!  I am trying to save the Bloodmaul from annihilation by the Bladespire clan, and Gruul's sons, who are backing them.\n\nI trust that you will be the one to aid our secret society and deliver us into freedom.", sourceObjectiveStatus = "unverified-source-field" }
quests[11058] = { id = 11058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Apexis Relic", description = "Long ago a now-extinct sect of the arakkoa known as the Apexis lived here.  Remnants of their civilization are still present.  We call them apexis relics.\n\nWhat we know about them is that, when properly used, they grant a boon.  Each relic presents a colored sequence which, when the crystals are pressed in the correct order, leads through a series of levels, each harder than the last.\n\nAn apexis shard is needed to power the relic.  Return when you have attained the insight of the apexis vibration.", sourceObjective = "Gain Apexis Vibrations from an Apexis Relic.", progress = "Have you learned how to use the apexis relic yet?  Both we and the Sha'tari Skyguard just to the north are interested in what you learn about them.", completion = "<Chu'a'lor nods his heads at you in satisfaction at your accomplishment.>\n\nYou have a quick mind, {name}.  It took us much longer to successfully make use of the relic.\n\nNow that you know how, you can do so as much as you care to.  Just remember that they require an apexis shard to power them.", sourceObjectiveStatus = "unverified-source-field" }
quests[11059] = { id = 11059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guardian of the Monument", description = "You've figured out how to use the single-person relics, but as you may have seen, there are bigger ones, which they surround.\n\nThese larger apexis monuments function in much the same way, but they take 35 apexis shards to activate.\n\nOf greater concern to us are the guardians that are summoned through their use.  These crystal constructs turned on their arakkoan masters long ago, and now endanger Ogri'la.\n\nWe would ask that you destroy one and bring us proof.", sourceObjective = "Collect an Apexis Guardian's Head.", progress = "We abhor violence, but at least the construct that we have sent you against isn't a living being.\n\nSpeaking of which, do you have the head?", completion = "<Chu'a'lor beams at you with obvious respect.>\n\nNot only are we impressed with the mental alacrity of you and your friends, but we are indebted to you, as is all of Ogri'la and the Skyguard, for helping to protect our way of life here.\n\nAnd remember, {name}, at any time you can gather others and return to any of those larger apexis monuments to make use of them; as long as you have enough apexis shards to power it that is.", sourceObjectiveStatus = "unverified-source-field" }
quests[11060] = { id = 11060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Crystalforged Darkrune", progress = "Da demons are making da Forge Camp: Wrath bigger.  Soon, dey be too big and crush us.  You crush dem first!\n\nShartuul's transporter is da key, but it protected by a magic shield and a demon called a degrader.  Us powerful warlock, and make special darkrune dat give you control of da degrader.  {race} give Gahkdarkrune, us give {race} crystalforged darkrune back.\n\nTake control of da degrader and possess as many of da demons dat come through da gate as you can ta stop dem!", completion = "Little {race}, remember, when you control da degrader, you use its hammer ta smash da warp-gate's shield and let loose da demon within.\n\nDen you crush dat demon and control it.  Den another demon come and you control it, until da eredar overseer come.\n\nDen you crush him too!!!" }
quests[11061] = { id = 11061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Father's Duty", description = "As to that other magical flask, it can only be obtained from one spot: Bash'ir Landing.  It's an ethereal base, and they aren't too friendly with outsiders, so it might be a little dangerous to obtain.\n\nWhere's Bash'ir Landing, you ask?  Well, if you get on your flying steed and head north by northeast, well past Forge Camp: Wrath, you'll eventually spot it.  The Bash'ir crystalforge itself is at the northeast corner of the landing.\n\nThank you for doing this, {name}.  It'll mean the world to our sons!", sourceObjective = "Collect an Unstable Flask of the Sorcerer for him.", progress = "That sorcerer's flask is sure to make my boys more intelligent than they already are, and that should help immensely with what they'll need to do once they're in the Sha'tari Skyguard.", completion = "We can't thank you enough, {name}!\n\nNow with these two flasks, unstable though they may be, we'll be able to send one of our boys north to the Skyguard Outpost.\n\nHere, just wait a moment and we'll call for one of them.", sourceObjectiveStatus = "unverified-source-field" }
quests[11062] = { id = 11062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Skyguard Outpost", description = "{name}, we were wondering if you might be willing to visit our friends just to the north at the Skyguard Outpost?\n\nSky Commander Keller and his Skyguard are here running missions for our mutual protection, and he's asked us to send along anyone that we feel would excel at helping out.\n\nThat would be you!\n\nHead up there as soon as you can, and please, give him our regards.", sourceObjective = "Speak with Sky Commander Keller at the Skyguard Outpost in the Blade's Edge Mountains.", completion = "Welcome ta the Skyguard Outpost!  I built it with me own hands ya know.\n\nYeah, the whole thing!\n\n<The sky commander looks serious.>\n\nSo, ye must be lookin' ta spoil for a fight if ye're here talkin' ta me.  It was kind of old Chu'a'lor ta send ye along.  We can always use fresh meat for the grinder around here.\n\nIf ye don't mind, I'd like ya ta start by having a talk with my sergeant across the way: Vanderlip.  Don't mind her tongue, though it be sharper than the greatsword she be carrying.", sourceObjectiveStatus = "unverified-source-field" }
quests[11063] = { id = 11063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Earning Your Wings...", sourceObjective = "So you wanna join the Skybreakers, eh? You've certainly proven yourself an able Dragonmaw but that means nothing in the skies of Outland. The question has to be answered: CAN YOU FLY?\n\nAnd I don't just mean being able to mount up on a nether drake and delivering a shipment of crystals to the fort like those transporter scrubs. I'm talking about being the best... The top orc...\n\nOver to the west there are six riders. Defeat them all and I will grant you Skybreaker wings.", sourceObjectiveStatus = "unverified-source-field" }
quests[11064] = { id = 11064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonmaw Race: The Ballad of Oldie McOld", description = "Don't let the gray hair fool you, grunt. I'm still ten times the rider that you are! And don't go thinking that this old dog doesn't have any tricks up his sleeve.\n\nNow all you gotta do is follow me and try not to get knocked down off your mount. If you can do that, Oldie will admit defeat.\n\nWe'll lift off as soon as you're ready.", sourceObjective = "Follow Murg \"Oldie\" Muckjaw while attempting to stay on your flying mount. Should you defeat Murg \"Oldie\" Muckjaw, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.", completion = "Pumpkins? Oh how the mighty have fallen... I am certain the other riders will prove to be much more challenging.", sourceObjectiveStatus = "unverified-source-field" }
quests[11065] = { id = 11065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrangle Some Aether Rays!", description = "Wanna help the Skyguard and Ogri'la?\n\nJust hear me out before you walk away, <hot stuff/girly>.  We're in need of remounts!  The bombing runs and missions to Bash'ir Landing have taken a toll on our mounts.\n\nThe aether rays that fly around Vortex Summit, and the Crystal Spine to the northeast, look like they'd do just fine.  You don't even have to bring them back here, though that would be nice.  Just break and rope them, and we'll track them down later.\n\nThink you can wrangle me up some?", sourceObjective = "Use the Wrangling Rope to capture 5 Aether Rays.", progress = "You wrangle me some aether rays yet?  You look like you might have some skill with rope, so it shouldn't take you too long.", completion = "Woo hoo!  Nice job, {name}!  Those rays are going to make excellent mounts!\n\nStick around kid... the Sha'tari Skyguard can always use a man of your obvious talents!", sourceObjectiveStatus = "unverified-source-field" }
quests[11066] = { id = 11066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrangle More Aether Rays!", description = "So, I hope that you're up to helping us wrangle up even more aether rays!  From what I can see, you're a natural with the rope!  And it's for a good cause, because not only do we get fresh mounts, but it helps us to protect Ogri'la, which the ogres appreciate.\n\nRemember, the aether rays fly around Vortex Summit, and the Crystal Spine to the northeast.\n\nThink you can wrangle me up some more?", sourceObjective = "Use the Wrangling Rope to capture 5 Aether Rays.", progress = "You're doing great work for us, {name}.  I want you to know that we really appreciate everything that you're doing to keep us stocked up in fresh mounts!", completion = "You continue to amaze me!  Tell you what... why don't you come back tomorrow and we'll let the rope cool off for now?\n\n<Khatie laughs.>\n\nThank you so much, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11067] = { id = 11067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonmaw Race: Trope the Filth-Belcher", description = "Dragonmaw treat you right, {name}. Even a worn out cursed being like me is given a chance. Now if you want to prove your worth to the Skybreakers, you will have to defeat me.\n\nI'm going to shake you off my tail like a bad case of fleas...\n\nWe'll lift off when you are ready.", sourceObjective = "Follow Trope the Filth-Belcher while attempting to stay on your flying mount. Should you defeat Trope the Filth-Belcher, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.", completion = "Interesting... Your next match will undoubtedly prove much more difficult. Corlok is no slouch.", sourceObjectiveStatus = "unverified-source-field" }
quests[11068] = { id = 11068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonmaw Race: Corlok the Vet", description = "You are challenging ME? Don't make me laugh!\n\nYou're serious? Very well then! All you need to do is not die. You can manage to not die, right?? Even if I'm hurling skulls at you and flying circles around your pathetic riding skills?\n\nJust let me know when you're ready and we'll lift off.", sourceObjective = "Follow Corlok the Vet while attempting to stay on your flying mount. Should you defeat Corlok the Vet, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.", completion = "The next two riders were the two top pilots that the dwarves and orcs of Azeroth had to offer. You stand no chance!", sourceObjectiveStatus = "unverified-source-field" }
quests[11069] = { id = 11069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonmaw Race: Wing Commander Ichman", description = "Three years I spent in that hell hole. Three years a prisoner of war to the damnable Frostwolf Clan. Made to sit in their tower and listen to them endlessly whine about the bridge to Dun Baldar. About how it's \"unfair\" that blah, blah, blah, blah... War isn't fair! To hell with 'em all!\n\nThe minute I was freed I left that place forever and came here to start a new life. Now Mulv and I are vying for the top orc spot. If you want it, you're gonna have to go through me, scrub.\n\nWe go when you're ready.", sourceObjective = "Follow Wing Commander Ichman while attempting to stay on your flying mount. Should you defeat Wing Commander Ichman, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.", completion = "I don't believe it! Mulverick is your next challenge. There's no way you'll survive that match.", sourceObjectiveStatus = "unverified-source-field" }
quests[11070] = { id = 11070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonmaw Race: Wing Commander Mulverick", description = "Three years of blood, sweat and tears. Mostly tears... The amount of crying that a hardened soldier does when it comes down to all-out war is amazing!\n\n\"They're jumping into our tower with their horses!\" \"Why is their base so well defended?\" \"They're taking our relief hut, I'm going A.W.O.L.!\"\n\nWimps...\n\nI took the first train out of \"cry-town\" the minute the Dark Portal opened. Now I'm a top gun for the Dragonmaw. If you want to be top orc, you'll have to defeat me.\n\nWe go when you are ready.", sourceObjective = "Follow Wing Commander Mulverick while attempting to stay on your flying mount. Should you defeat Wing Commander Mulverick, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.", completion = "Well it looks like it's just you and the captain now, grunt. Good luck! You're gonna need it!", sourceObjectiveStatus = "unverified-source-field" }
quests[11071] = { id = 11071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonmaw Race: Captain Skyshatter", description = "You dare challenge Skyshatter? The world around you will fall into darkness as the heavens are torn asunder by my meteors.\n\nYou stand no chance, soldier. Yet it is your desire to die...\n\nI will entertain this morbid obsession if only to prove a point to any that might foolishly dream of making the same mistake.\n\nWe ride when you are ready!", sourceObjective = "Follow Captain Skyshatter while attempting to stay on your flying mount. Should you defeat Captain Skyshatter, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.", completion = "I never dreamed any would be skilled enough to defeat Skyshatter. You do know what this means, right? You are now the top orc! You must defend your title.", sourceObjectiveStatus = "unverified-source-field" }
quests[11072] = { id = 11072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adversarial Blood", description = "The descendants held prisoner by the Skettis talonpriests are listed in this book: Gezzarak the Huntress, Karrog the crystal giant, the heretic known as Darkscreecher Akkarai and Vakkiz the Windrager.  They will all need to be slain before Terokk returns to this world.\n\nYou will need the scrolls carried by the time-lost arakkoa to call them forth at the summoning circles in Skettis.  Bring me a token from each one.  These are powerful beings you will be facing; you would do well to bring friends.", sourceObjective = "Find the Skull Piles in the middle of the summoning circles of Skettis. Summon and defeat each of the descendants by using 10 Time-Lost Scrolls at the Skull Pile. Return to Hazzik at Blackwind Landing with a token from each.", sourceObjectiveStatus = "unverified-source-field" }
quests[11073] = { id = 11073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terokk's Downfall", description = "I... I've turned a blind eye to your dealings with the arakkoa prisoner, {name}.  It looks like your instincts to cooperate with him were right.\n\nYou must understand... I would've faced a mutiny in my current state if I endorsed your efforts to bring Terokk to this world.\n\nTake the items that Hazzik prepared for you and go ahead with your plan.  I will command my men to back you up when the time comes.  I recommend that you bring a force of your own as well.  I fear you'll only get one chance at this.", sourceObjective = "Take the Time-Lost Offering prepared by Hazzik to the Skull Pile at the center of Skettis and summon and defeat Terokk. Return to Sky Commander Adaris when you've completed this task.", progress = "Is it done, {name}?  Has Terokk been defeated?", completion = "You've made us all very proud, {name}.  I'll send word of your deeds back to Shattrath.  The Skyguard will be forever in your debt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11074] = { id = 11074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tokens of the Descendants", description = "The descendants held prisoner by the Skettis talonpriests are listed in this book.  Gezzarak the Huntress, Garokk the Crystal Giant, the heretic known as Darkscreecher Akkarai and Vekkaz the Windrager.  They will all need to be slain before Terokk returns to this world.\n\nYou will need the scrolls carried by the time-lost arakkoa and burn them at the summoning circles all over Skettis.  Bring me a token from each one.  These are powerful beings you will be facing; you would do well to bring friends.", sourceObjective = "Collect Time-Lost Scrolls from the time-lost arakkoa in Skettis and bring them to a Skull Pile inside a summoning circle in Skettis. Summon and defeat the descendants of Terokk's adversaries and return to Hakkiz with Akkarai's Talon, Garokk's Spine, Vekkaz's Scale and Gezzarak's Claw.", progress = "I require a token from each of the descendants of Terokk's greatest adversaries.  Only then will we be ready to summon Terokk.", completion = "Excellent!  Take this.  I've prepared this bundle with the items you obtained.  They will allow you to summon Terokk.\n\nBeware, {name}.  He is the most powerful arakkoa to ever exist.  Do not underestimate him!", sourceObjectiveStatus = "unverified-source-field" }
quests[11075] = { id = 11075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Netherwing Mines", description = "Your help is required at the Netherwing Mines, overseer {name}.\n\nTwo days ago our mining operations came to a grinding halt when we made a grim discovery. A miner was working in the depths of the mine and struck his pick upon an unusual crystal formation. Unfortunately, this crystal formation was attached to a very angry nether dragon. The beast woke from its slumber and annihilated all of our workers.\n\nReport to the Mistress of the Mines. They await you at the mouth of the mines, southwest of here.", sourceObjective = "Seek out the Mistress of the Mines on Netherwing Ledge.", completion = "The miners are working hard but none dare step foot further into the mines. They choose death rather than being forced to mine deeper! It is going to be your job to carry out the duties and tasks that they failed to complete.", sourceObjectiveStatus = "unverified-source-field" }
quests[11076] = { id = 11076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Picking Up The Pieces...", description = "Much of our hard work lies scattered about in these mines. Carts full of cargo are littered across every inch of this mine! We just can't get to any of it with the current infestation.\n\nThat's where you come in, {name}. Your daily duty here at this mine is to collect the cargo left behind by the miners and deep mine workers.\n\nGather the nethermine cargo and return it to me or my sister.", sourceObjective = "The Mistress of the Mines at the Netherwing Mines in Shadowmoon Valley wants you to recover 15 Nethermine Cargo crates.", progress = "Have you gathered the cargo?", completion = "Well done, {name}. Return tomorrow for another mission into the depths of the mine.", sourceObjectiveStatus = "unverified-source-field" }
quests[11077] = { id = 11077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragons are the Least of Our Problems", description = "That dragon waking up riled up a host of other nasty creatures in these mines. Two types are proving to be a thorn in the side of the Dragonmaw: Nethermine flayers and Nethermine ravagers. You must help us by killing them off. All I ask is your involvement once per day.\n\nGet in there and kill as many as you can!", sourceObjective = "The Dragonmaw Foreman at the Netherwing Mines in Shadowmoon Valley wants you to kill 15 Nethermine Flayers and 5 Nethermine Ravagers.", progress = "How's that flayer infestation problem coming along?", completion = "That'll be enough for today, overseer. Come back tomorrow for another round of clean up.", sourceObjectiveStatus = "unverified-source-field" }
quests[11078] = { id = 11078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Rule The Skies", description = "As ye've flown around, ye must have noticed the dragons above.  I trust ye haven't fallen victim ta their rage.  Help us put an end ta it, {name}!\n\nRivendark and Obsidia lord over this terrace, while Insidion and Furywing rule the skies over yon terrace ta the northeast.  Each has a perch on their respective domains.  I be wondering if ye and yer friends will go ta one, <lad/lass>, break open an egg with 35 apexis shards and attract the dragon down.\n\nBring me some teeth as proof.", sourceObjective = "Collect Dragon Teeth.", progress = "How fares yer mission, {name}?  I needn't tell ye how important this be ta our continued ability ta fly around up here.", completion = "Yes!  Those teeth look like they be sharp enough ta cut through just about anything!\n\nAnd let me encourage ye and yer friends ta keep up the good work!  Those dragons be fierce predators that make the skies wholly unsafe.\n\nYe might have noticed, too, the dragon scales.  I hear they be good fer making powerful cloaks if ye get one o' each o' their scales.  And if yer not happy with the cloak ya get, I'll be willing ta trade ye an apexis crystal fer it.", sourceObjectiveStatus = "unverified-source-field" }
quests[11079] = { id = 11079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fel Whip For Gahk", description = "Gahk think being smart is dumb sometimes.  Gahk not want to think.  Me want little {race} to smash big demons!\n\nDey have some chiefs, and da chiefs all have whips to hurt da little demons.  You bring Gahk a whip!\n\nYou challenge demon chief in forge camps at burning, green, fel crystal prism.  Use 35 apexis shards to get dem to come.  Dey called Galvanoth, Braxxus, Zarcsin and da Mo'arg Incinerator.", sourceObjective = "Collect a Fel Whip.", progress = "Yous have da whip?", completion = "Gahk like whip.  Maybe Gahk take whip and beat demons with it!\n\nMe say to {race} that {race} summon demon chiefs anytime {race} have friends and many shards.", sourceObjectiveStatus = "unverified-source-field" }
quests[11080] = { id = 11080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Relic's Emanation", description = "Now that you have felt the enlightening vibrations of the apexis relics, it is time for you to further your understanding of their workings.  We are very eager to benefit from your observations!\n\nAs you progress in your ability to attune to the relics, you will gain a higher level of knowledge.  This recognition will come in the form of an emanation from the relic.\n\nReturn to us when you have attained such an emanation.", sourceObjective = "Gain Apexis Emanations from an Apexis Relic.", progress = "Do you have the emanation from the apexis relic about you?", completion = "You continue to amaze us with your acumen as concerns the relics, {name}.  May we suggest that you practice with the relics at least once a day to maintain such a sharp edge to your mental acuity?", sourceObjectiveStatus = "unverified-source-field" }
quests[11081] = { id = 11081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Murkblood Revolt", description = "This document outlines a revolt planned by the Murkblood broken. It seems that the dragon was to be used as a diversion to draw attention away from their escape. Looking at all of the corpses littering the mine, it would be safe to assume that their plans failed.\n\nReturn the escape plans to the Mistress of the Mines.", sourceObjective = "Take the Murkblood Escape Plans to the Mistress of the Mines.", progress = "What's this?", completion = "Excellent work, overseer. Mor'ghor will hear of your outstanding service to the Dragonmaw.\n\nNow back to these Murkblood dogs. They plan an escape, eh? Dare they defy the one true lord of Outland? Their masters will pay for this!", sourceObjectiveStatus = "unverified-source-field" }
quests[11082] = { id = 11082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeker of Truth", description = "These miners are far too stupid to concoct any type of escape plan. We must find and punish the source. Venture into the depths of the mine and seek out the Murkblood overseers. If they have not been overcome by the denizens of the mine, they will undoubtedly be hiding.\n\nOnce you locate one, interrogate him until he reveals the true mastermind behind the escape. Return to me with the identity of this traitor and the hand of the overseer.", sourceObjective = "Find a Murkblood Overseer and interrogate him. Return to the Mistress of the Mines with the Murkblood information and the Hand of the Overseer.", progress = "Well? What's taking so long?", completion = "Nothing to say? Perhaps as he lies bleeding to death on the floor of this cursed mine he will remember... Remember what it means to cross the forces of Illidan!", sourceObjectiveStatus = "unverified-source-field" }
quests[11083] = { id = 11083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crazed and Confused", description = "Don't worry about this dragon, {name}. We've got plans for it...\n\nDeeper in this mine is a band of crazed Murkblood. After the dragon broke out, they were cut off from the exit. Somehow, after a mere 2 days of isolation, they've lost all sense of decency.\n\nThey've resorted to cannibalism and the promotion of mayhem. We don't need that kind of madness in this place. Find 'em and kill 'em. All of 'em.", sourceObjective = "Ronag the Slave Driver in the Netherwing Mines of Shadowmoon Valley wants you to slay the Crazed Murkblood Foreman and 5 Crazed Murkblood Miners.", progress = "Is the problem \"solved\"?", completion = "Yeah, I don't understand it... You would think that they wouldn't even be that hungry after 2 days. Murkblood...\n\n<Ronag shakes his head.>\n\nDamn they're stupid...", sourceObjectiveStatus = "unverified-source-field" }
quests[11084] = { id = 11084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stand Tall, Captain!", description = "Well, well, well... still alive I see. That's good, because Mor'ghor has requested your presence in his tower at once. Get a move on!", sourceObjective = "Speak with Overlord Mor'ghor at Dragonmaw Base Camp in Shadowmoon Valley.", completion = "<Mor'ghor nods.>\n\nThat's right, I said captain. You've earned another promotion, {name}.\n\nYou certainly don't work like any fel orc I've ever seen. Keep this up and you might make overlord some day.\n\nNow get out there and take command. I would suggest you try and earn your Skybreaker wings.", sourceObjectiveStatus = "unverified-source-field" }
quests[11085] = { id = 11085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape from Skettis", description = "Hail, {name}.  I thank you for coming to my aid.\n\nThe arakkoa's monstrous birds knocked me from my nether ray while on a scouting mission.\n\nLet's get out of here, while we can.", sourceObjective = "Escort the Skyguard Prisoner to safety and report to Sky Sergeant Doryn.", progress = "Yes, {name}?", completion = "Thank you for rescuing one of our scouts, {name}.  We lose good people every day and there aren't enough new recruits to replace them.", sourceObjectiveStatus = "unverified-source-field" }
quests[11086] = { id = 11086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disrupting the Twilight Portal", description = "One of your responsibilities as a captain of Dragonmaw is to snuff out Burning Legion activity in Outland. It is your duty to silence those that defy Lord Illidan!\n\nThe demons foolishly attempt to stabilize the portal found on the Twilight Ridge of western Nagrand. They must pay for their treachery, and you will be the orc that collects on their debt.\n\nTravel to the Twilight Ridge and lay waste to its inhabitants. You will be responsible for making at least one attack per day on their fortifications.", sourceObjective = "Overlord Mor'ghor at Dragonmaw Base Camp in Shadowmoon Valley wants you to kill 20 Deathshadow Agents.", progress = "It was our lord, after all, that banished the demons from Outland and closed their portals. All should bow down to the magnificence of Illidan.", completion = "Excellent work, captain! Lord Illidan will hear of your heroism!", sourceObjectiveStatus = "unverified-source-field" }
quests[11087] = { id = 11087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "HYJAL FLAG", description = "Seven vials were drawn from the Well of Eternity by Illidan.  He poured three into the lake on top of Mount Hyjal and a second Well of Eternity was created.  For years the rest were believed lost.\n\nWith the opening of the Dark Portal, we've come to know that he gave one each to his lieutenants Kael'thas and Vashj.  Retrieve what remains of them; we will need them as foci to open a gateway to any events tied to Mount Hyjal, recent or ancient.  The outcome of the Battle of Mount Hyjal must be preserved.", sourceObjective = "Soridormi at Caverns of Time wants you to retrieve Vashj's Vial Remnant from Lady Vashj at Coilfang Reservoir and Kael's Vial Remnant from Kael'thas Sunstrider at Tempest Keep.", sourceObjectiveStatus = "unverified-source-field" }
quests[11089] = { id = 11089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Soul Cannon of Reth'hedron", description = "Reth'hedron now lords over the Twilight Ridge of Nagrand. An eredar of such power being loosed upon this world does not bode well for the Illidari. Alas, we do not have the resources required to slay Reth'hedron. Not with the war the Sha'tar have brought to the Black Temple. No... I have a better plan.\n\nYou will subdue Reth'hedron, banishing him back through the Twilight Portal. For this a soul cannon must be fashioned.\n\nReturn to me with the materials on this list.", sourceObjective = "Illidari Lord Balthas at the Dragonmaw Base Camp in Shadowmoon Valley wants you to bring him 2 Felsteel Bars, 1 Adamantite Frame, 1 Khorium Power Core and 1 Flawless Arcane Essence.", progress = "Have you gathered the components required to fashion the soul cannon?", completion = "<Balthas deftly combines the components you brought him.>\n\nYou are now ready for the second phase of the plan, captain.", sourceObjectiveStatus = "unverified-source-field" }
quests[11090] = { id = 11090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Subdue the Subduer", description = "<Balthas holds up an alien looking device.>\n\nThis is a soul cannon. Its effects are devastating when attuned. This one is attuned to my blood. The same blood flowing through the veins of Reth'hedron - my brother. Aye, his misplaced allegiance will be the end of him.\n\nTake the cannon and fly to the Twilight Ridge in western Nagrand. Locate Reth'hedron and fire! You must stay on your mount and within range for the effects to take hold. Stand your ground against him and he will have no choice but to flee!", sourceObjective = "Illidari Lord Balthas at Dragonmaw Base Camp in Shadowmoon Valley has tasked you with using the Soul Cannon on Reth'hedron the Subduer in Nagrand.\n\nYou must also return the Soul Cannon.", progress = "Is it done?", completion = "He will be back, but for now the Legion's war against Lord Illidan is weakened. He shall know of your deeds, captain.", sourceObjectiveStatus = "unverified-source-field" }
quests[11091] = { id = 11091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Thank You", description = "You honor us with your efforts on our behalf.  And now there is someone that we would like for you to meet.\n\nJho'nass is our most trusted quartermaster.  He maintains a stock of goods that we provide for sale to only the most dedicated of friends to Ogri'la.\n\nYou are one such friend, {name}.\n\nWhen you find the time, go and speak with him.  As we understand it, he has prepared a little something for you as a token of our appreciation.", sourceObjective = "Speak with Jho'nass at Ogri'la in the Blade's Edge Mountains.", completion = "Hey, man, that's great.  We hear you've been doing good things.  That's cool.  We've got a feeling that you're going to make things right for us here in Ogri'la, and keep us safe, and everything nice and mellow.\n\nHere, take this.  It's nothing much, just a care package that we whipped up as a thanks for your effort.\n\nFeel free to look around at our goods.  We have a lot of really choice stuff that you're gonna want to get.", sourceObjectiveStatus = "unverified-source-field" }
quests[11092] = { id = 11092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hail, Commander!", description = "Captain {name}!\n\n<Taskmaster Varkule salutes you.>\n\nOverlord Mor'ghor has asked to see you in his chambers at once!", sourceObjective = "Speak with Overlord Mor'ghor at Dragonmaw Base Camp in Shadowmoon Valley.", completion = "Lord Illidan himself has asked that I promote you to the rank of commander! This is unprecedented. You will be the first Dragonmaw to reach such a rank outside of the Black Temple.", sourceObjectiveStatus = "unverified-source-field" }
quests[11093] = { id = 11093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungry Nether Rays", description = "Nether rays are surprisingly loyal and obedient once properly trained.  Unfortunately the war on Skettis is taking a toll on them.\n\nWe have dozens of sorties a day - the poor fellows rarely get a break.  And with recent shortages on feed, if those blasted birdmen don't kill them on a mission then starvation will.\n\nIf you can lend a hand, take one of our rays to the woods in the south.  They don't mind warp chaser meat as long as it's a fresh kill.", sourceObjective = "Use the Nether Ray Cage in the woods south of Blackwind Landing and slay Blackwind Warp Chasers near the Hungry Nether Ray. Return to Skyguard Handler Deesak when you've completed your task.", progress = "You're back!  Did your ray behave well?", completion = "Thanks for taking care of the ray, {name}.  Goodness knows these guys fly much better when they're well-fed.  We don't want our boys getting shot down because their ray was too weak to fly.", sourceObjectiveStatus = "unverified-source-field" }
quests[11094] = { id = 11094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Them All!", description = "Commander {name}, stand at attention! You are to take a battalion of Skybreakers and sack the Scryers' outpost located at the foot of the Netherwing Fields. With the Sanctum of the Stars destroyed, our lines of communication to our posts at Eclipse Point and Illidari Point will once more be open.\n\nGo now! Use this flare gun to signal the Skybreakers for the attack!", sourceObjective = "Deliver news of your mission along with the Dragonmaw Flare Gun to Arcanist Thelis at the Sanctum of the Stars in Shadowmoon Valley.", progress = "Settle down, child.", completion = "It is good that you came to us. Perhaps we can use this attack to our advantage and turn the tables on the Dragonmaw.", sourceObjectiveStatus = "unverified-source-field" }
quests[11095] = { id = 11095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Commander Hobb", description = "The Dragonmaw only dare attack us when our guard is down. They would face certain defeat if they were to attack us while we were prepared.\n\nI want you to let them come, {name}.\n\n<Thelis nods.>\n\nYes... a trap. Take this flare that their overlord gave you and deliver it to Commander Hobb. He is standing guard right outside this building.", sourceObjective = "Give the Dragonmaw Flare to Commander Hobb at the Sanctum of the Stars in Shadowmoon Valley.", progress = "<Hobb nods.>", completion = "<Hobb grins.>\n\nThe deadliest trap ever laid...", sourceObjectiveStatus = "unverified-source-field" }
quests[11096] = { id = 11096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Threat from Above", description = "So you want to join the Skyguard?  Well, I know you can fly... but can you fight?\n\nThe Skyguard is sworn to protect Shattrath from the dangers that loom above us, both near and far.  The Gordunni ogres who dwell in the Barrier Hills to the north are an immediate threat to us.\n\nReaching the ogres has been problematic for Shattrath's ground units.  That's where we come in.  See what you can do to help contain them.", sourceObjective = "Slay any 20 Gordunni Ogres in the Barrier Hills and return to Yuula in Shattrath City.", progress = "Have you completed your task, {name}?", completion = "Good job, ace.  I've a feeling you're going to fit in well with us.", sourceObjectiveStatus = "unverified-source-field" }
quests[11097] = { id = 11097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deadliest Trap Ever Laid", description = "Take these Scryer medals. Mor'ghor will need proof of \"victory\" once this is over. He will recognize them as coming from the corpses of fallen Scryer soldiers.\n\nNow all that remains is to use the signal flare to alert the Dragonmaw raiders. We will crush them when you are ready. Just give me the word.", sourceObjective = "Assist Commander Hobb and the Scryers in defending the Sanctum of the Stars. Once all of the Dragonmaw forces have been defeated, return to Overlord Mor'ghor at Dragonmaw Base Camp with the Scryer Medals.", progress = "Did you crush them under your boot, commander?", completion = "<Mor'ghor laughs.>\n\nHAH! I knew you wouldn't let me down, commander! I want you to lead a raid on the Sanctum of the Stars at least once per day. They will have no choice but to leave Shadowmoon!", sourceObjectiveStatus = "unverified-source-field" }
quests[11098] = { id = 11098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Skettis!", description = "The Barrier Hills are only one of the fronts where we've been deployed.  A less immediate but far more dangerous threat looms from beyond the Skethyl Mountains, from within the arakkoa city of Skettis.\n\nA few months ago our scouts detected a huge increase in arakkoa activity there.  Several attacks against Shattrath followed.  We've stationed forces outside of their city since.\n\nTake these explosives to Sergeant Doryn at Blackwind Landing, just outside Skettis.  Tell him you're a new recruit.", sourceObjective = "Take the Explosives Package to Sky Sergeant Doryn at Blackwind Landing outside Skettis.", progress = "You've something for me, lad?", completion = "Thanks for the supplies; we'll put them to good use!  A new recruit?  Well, let's see what you're made of.", sourceObjectiveStatus = "unverified-source-field" }
quests[11099] = { id = 11099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Them All!", description = "Commander {name}, stand at attention! You are to take a battalion of Skybreakers and sack the Aldor outpost located northwest of our beloved Black Temple. With the Altar of Sha'tar destroyed, our lines of communication to our posts at Coilskar will once more be open.\n\nGo now! Use this flare gun to signal the Skybreakers for the attack!", sourceObjective = "Deliver news of your mission and the Dragonmaw Flare Gun to Anchorite Ceyla at the Altar of Sha'tar.", progress = "Settle down, child.", completion = "It is good that you came to us. Perhaps we can use this attack to our advantage and turn the tables on the Dragonmaw.", sourceObjectiveStatus = "unverified-source-field" }
quests[11100] = { id = 11100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Commander Arcus", description = "The Dragonmaw only dare attack us when our guard is down. They would face certain defeat if they were to attack us while we were prepared.\n\nI want you to let them come, {name}.\n\n<Ceyla nods.>\n\nYes... a trap. Take this flare that their overlord gave you and deliver it to Commander Arcus. He is standing guard right outside this building.", sourceObjective = "Give the Dragonmaw Flare to Commander Arcus at the Altar of Sha'tar in Shadowmoon Valley.", progress = "<Arcus nods.>", completion = "<Arcus grins.>\n\nThe deadliest trap ever laid...", sourceObjectiveStatus = "unverified-source-field" }
quests[11101] = { id = 11101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deadliest Trap Ever Laid", description = "Take these Aldor medals. Mor'ghor will need proof of \"victory\" once this is over. He will recognize them as coming from the corpses of fallen Aldor soldiers.\n\nNow all that remains is to use the signal flare to alert the Dragonmaw raiders. We will crush them when you are ready. Just give me the word.", sourceObjective = "Assist Commander Arcus and the Aldor in defending the Altar of Sha'tar. Once all of the Dragonmaw forces have been defeated, return to Overlord Mor'ghor at Dragonmaw Base Camp with the Aldor Medals.", progress = "Did you crush them under your boot, commander?", completion = "<Mor'ghor laughs.>\n\nHAH! I knew you wouldn't let me down, commander! I want you to lead a raid on the Altar of Sha'tar at least once per day. They will have no choice but to leave Shadowmoon!", sourceObjectiveStatus = "unverified-source-field" }
quests[11102] = { id = 11102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombing Run", description = "You can fly around as a crow... so what!  Ever annihilate something on the ground while you were flying?  Want to?\n\nForge Camp: Wrath and Forge Camp: Terror, to the north and south, are a major pain in my backside, as well as being a threat to peaceful Ogri'la.  With all of those fel cannons shooting down the Skyguard left and right, we can't get through there to take care of business.\n\nWant to prove yourself?  Take these bombs and knock out their ammo stacks.  Just don't let them shoot you down, too!", sourceObjective = "Use the Skyguard Bombs to destroy 15 Fel Cannonball Stacks.", progress = "You take out their stacks of fel cannonballs yet?", completion = "Well, well, well, I guess you had it in you after all.  Good work.  Maybe Old Man Keller was wrong about you after all.\n\n<Sky Sergeant Vanderlip smirks.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11103] = { id = 11103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sage No More", progress = "The power within your ring is malleable, though reversing your choice is not easy.  Are you sure you want to replace its current form?", completion = "The sands of time flow forwards easily.  They can be made to flow backward, but with great difficulty." }
quests[11104] = { id = 11104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restorer No More", progress = "The power within your ring is malleable, though reversing your choice is not easy.  Are you sure you want to replace its current form?", completion = "The sands of time flow forwards easily.  They can be made to flow backward, but with great difficulty." }
quests[11105] = { id = 11105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion No More", progress = "The power within your ring is malleable, though reversing your choice is not easy.  Are you sure you want to replace its current form?", completion = "The sands of time flow forwards easily.  They can be made to flow backward, but with great difficulty." }
quests[11106] = { id = 11106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defender No More", progress = "The power within your ring is malleable, though reversing your choice is not easy.  Are you sure you want to replace its current form?", completion = "The sands of time flow forwards easily.  They can be made to flow backward, but with great difficulty." }
quests[11107] = { id = 11107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bow to the Highlord", description = "I am unworthy to even carry a message directed at you, sir. Please forgive me for this indulgence. Overlord Mor'ghor has requested your presence in his chambers at once!", sourceObjective = "Speak to Overlord Mor'ghor at Dragonmaw Base Camp in Shadowmoon Valley.", completion = "You are the first highlord of the Dragonmaw, {name}. The master himself has chosen to come here to promote you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11108] = { id = 11108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Illidan Stormrage", description = "Come, highlord {name}. Illidan himself awaits us!", sourceObjective = "Meet Illidan Stormrage. Seek out Barthamus in the Lower City of Shattrath should you survive.", completion = "I was the first, you know. The abandoned child of a monster...\n\n<Barthamus shakes his head.>\n\nWe owe you everything, {name}. You have single-handedly shattered the Dragonmaw empire and gathered enough information to keep my brethren occupied for ten lifetimes.\n\nIt is not much but there is something that we can offer... My kin have each offered to join you on your mission in Outland. Simply ask and they will bond with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11109] = { id = 11109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jorus the Cobalt Netherwing Drake", sourceObjective = "It is an honor to meet you, {name}. We have all been keeping a close eye on your adventures and are grateful for all that you have done for the Netherwing Dragonflight.\n\nIf you choose me as your compatriot, I will fly you to the ends of this world and back. Whatever it is that you ask of me, I will do my best to comply.\n\nBe warned that you may only select one of us for your journeys in Outland. Once the selection has been made, you cannot change your mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[11110] = { id = 11110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malfas the Purple Netherwing Drake", sourceObjective = "It is an honor to meet you, {name}. We have all been keeping a close eye on your adventures and are grateful for all that you have done for the Netherwing Dragonflight.\n\nIf you choose me as your compatriot, I will fly you to the ends of this world and back. Whatever it is that you ask of me, I will do my best to comply.\n\nBe warned that you may only select one of us for your journeys in Outland. Once the selection has been made, you cannot change your mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[11111] = { id = 11111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onyxien the Onyx Netherwing Drake", sourceObjective = "It is an honor to meet you, {name}. We have all been keeping a close eye on your adventures and are grateful for all that you have done for the Netherwing Dragonflight.\n\nIf you choose me as your compatriot, I will fly you to the ends of this world and back. Whatever it is that you ask of me, I will do my best to comply.\n\nBe warned that you may only select one of us for your journeys in Outland. Once the selection has been made, you cannot change your mind.", sourceObjectiveStatus = "unverified-source-field" }
